args.command:
cd /bench/repo && cat > /tmp/fanin.awk <<'EOF'
# pass 1: collect decl names from internal/ files
FNR==1 { isinternal = (FILENAME ~ /(^|\/)internal\//) }
{
  if (pass==1) {
    if (isinternal && $0 ~ /^func /) {
      line=$0
      sub(/^func /,"",line)
      sub(/^\([^)]*\) */,"",line)
      if (match(line, /^[A-Za-z0-9_]+/)) {
        nm=substr(line, RSTART, RLENGTH)
        decl[nm]=1
        where[nm]=where[nm] FILENAME ":" FNR " "
      }
    }
  } else {
    # count call-like occurrences  name(
    s=$0
    while (match(s, /[A-Za-z0-9_]+\(/)) {
      tok=substr(s, RSTART, RLENGTH-1)
      if ($0 !~ ("^func +(\\([^)]*\\) *)?" tok "\\(")) cnt[tok]++
      s=substr(s, RSTART+RLENGTH)
    }
  }
}
END {
  if (pass==2) for (n in decl) printf "%d\t%s\t%s\n", cnt[n], n, where[n]
}
EOF
awk -v pass=1 -f /tmp/fanin.awk $(cat /tmp/gofiles.txt) > /dev/null; awk -v pass=1 -f /tmp/fanin.awk $(cat /tmp/gofiles.txt) 2>/dev/null | head -1; echo "run combined"; awk 'BEGIN{}'

cd /bench/repo && awk '
{
  s=$0
  while (match(s, /[A-Za-z0-9_]+\(/)) {
    tok=substr(s, RSTART, RLENGTH-1)
    if ($0 !~ ("^func +(\\([^)]*\\) *)?" tok "\\(")) cnt[tok]++
    s=substr(s, RSTART+RLENGTH)
  }
}
END { for (n in cnt) printf "%s\t%d\n", n, cnt[n] }
' $(cat /tmp/gofiles.txt) | sort > /tmp/counts.tsv && join -t $'\t' -1 1 -2 1 <(cut -f1 /tmp/decls.tsv | sort -u) /tmp/counts.tsv | sort -t $'\t' -k2 -nr | head -25

